insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('mug-printing', 'Mugs & Sublimation', 'මග් සහ සබ්ලිමේෂන්', 'Photo mugs, magic mugs, clocks and gifts printed with vivid, dishwasher-safe sublimation inks.', 'ඡායාරූප මග්, මැජික් මග්, ඔරලෝසු සහ තෑගි භාණ්ඩ — දීප්තිමත් සබ්ලිමේෂන් මුද්‍රණයෙන්.', 10) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('photo-framing', 'Photo Framing', 'ඡායාරූප රාමු', 'Wood, glass and LED frames for weddings, anniversaries and family portraits — printed and framed in-house.', 'විවාහ, සංවත්සර සහ පවුලේ ඡායාරූප සඳහා ලී, වීදුරු සහ LED රාමු — අපගේ වැඩමුළුවේම මුද්‍රණය කර රාමු කරයි.', 20) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('laser-cutting', 'Laser Cutting', 'ලේසර් කැපීම', 'Precise laser-cut names, shapes, signs and decor in MDF, wood and acrylic.', 'MDF, ලී සහ ඇක්‍රිලික් මත නිවැරදි ලේසර් කැපුම් නම්, හැඩතල සහ සැරසිලි.', 30) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('wood-engraving', 'Wood Engraving', 'ලී මත කැටයම්', 'Photos and messages engraved into wood plaques, boards and wood slices — a gift that lasts.', 'ලී පුවරු සහ ලී පෙති මත ඡායාරූප සහ පණිවිඩ කැටයම් කිරීම — කල් පවතින තෑග්ගක්.', 40) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('crystal-printing', 'Crystal Printing', 'ක්‍රිස්ටල් මුද්‍රණය', 'Your photo printed inside glass crystal blocks — elegant keepsakes and awards.', 'ඔබේ ඡායාරූපය ක්‍රිස්ටල් වීදුරු කුට්ටියක් තුළ — අලංකාර සිහිවටන සහ සම්මාන.', 50) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('banners', 'Banners & Large Format', 'බැනර් සහ විශාල මුද්‍රණ', 'Flex banners, backdrops and signage in any size for shops, events and campaigns. Priced per square foot.', 'කඩ, උත්සව සහ ප්‍රචාරණ සඳහා ඕනෑම ප්‍රමාණයක ෆ්ලෙක්ස් බැනර් සහ පසුබිම්. වර්ග අඩියට මිල.', 60) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('digital-printing', 'Digital Printing', 'ඩිජිටල් මුද්‍රණය', 'Business cards, flyers, certificates and everyday print jobs with fast turnaround.', 'විසිටින් කාඩ්, පත්‍රිකා, සහතික සහ දෛනික මුද්‍රණ කටයුතු ඉක්මනින්.', 70) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('plan-printing', 'Plan Printing', 'සැලසුම් මුද්‍රණය', 'A3 to A0 architectural and engineering plans in black & white or colour — send your PDF, collect the same day.', 'A3 සිට A0 දක්වා ගෘහ නිර්මාණ සහ ඉංජිනේරු සැලසුම් — ඔබේ PDF එක එවන්න.', 80) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('photo-enlargement', 'Photo Enlargement', 'ඡායාරූප විශාලනය', 'Large photo prints and canvas from your phone or camera, with optional retouching.', 'ඔබේ දුරකථනයෙන් හෝ කැමරාවෙන් විශාල ඡායාරූප සහ කැන්වස් මුද්‍රණ.', 90) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('t-shirt-printing', 'T-Shirt Printing', 'ටී-ෂර්ට් මුද්‍රණය', 'Custom T-shirts for teams, events, schools and businesses — single pieces or bulk.', 'කණ්ඩායම්, උත්සව, පාසල් සහ ව්‍යාපාර සඳහා ටී-ෂර්ට් — එකක් හෝ තොග වශයෙන්.', 100) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('edible-print', 'Edible Print', 'කෑමට ගත හැකි මුද්‍රණ', 'Food-safe photo prints on icing sheets for birthday and celebration cakes.', 'උපන්දින සහ සැමරුම් කේක් සඳහා අයිසිං කඩදාසි මත ආහාරයට සුදුසු ඡායාරූප මුද්‍රණ.', 110) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.categories (slug, name_en, name_si, description_en, description_si, sort_order) values ('custom-souvenirs', 'Custom Souvenirs', 'සිහිවටන භාණ්ඩ', 'Key tags, badges and personalised giveaways for weddings, schools and corporate events.', 'විවාහ, පාසල් සහ ආයතනික උත්සව සඳහා කී ටැග්, ලාංඡන සහ පුද්ගලීකරණය කළ තෑගි.', 120) on conflict (slug) do update set name_en = excluded.name_en, name_si = excluded.name_si, description_en = excluded.description_en, description_si = excluded.description_si, sort_order = excluded.sort_order;
insert into public.products (category_id, slug, name_en, name_si, short_description_en, short_description_si, description_en, description_si, order_type, pricing_mode, base_price, price_per_sqft, min_sqft, production_days, express_days, express_surcharge_percent, design_fee, allow_customer_artwork, allow_design_service, requires_artwork, images, specs, is_featured, sort_order) select c.id, 'photo-mug-white-11oz', 'Photo Mug — White 11oz', 'ඡායාරූප මග් — සුදු 11oz', 'Your photos and words on a classic ceramic mug.', 'සම්භාව්‍ය සෙරමික් මග් එකක ඔබේ ඡායාරූප සහ වචන.', 'A glossy white ceramic mug printed edge to edge with your photos, names or logo. Dishwasher and microwave safe. Our designer sends you a proof before printing.', 'ඔබේ ඡායාරූප, නම් හෝ ලාංඡනය මුද්‍රණය කළ දිලිසෙන සුදු සෙරමික් මග් එකක්. මුද්‍රණයට පෙර අපගේ නිර්මාණකරු සාම්පලයක් එවයි.', 'fixed'::public.order_type, 'fixed'::public.pricing_mode, 1200, null, null, 2, 1, 50, 300, true, true, true, '[]'::jsonb, '[{"label_en":"Capacity","value_en":"11 oz / 330 ml"},{"label_en":"Print","value_en":"Full-wrap sublimation"},{"label_en":"Care","value_en":"Dishwasher & microwave safe"}]'::jsonb, true, 10 from public.categories c where c.slug = 'mug-printing' on conflict (slug) do nothing;
insert into public.product_price_tiers (product_id, min_quantity, discount_percent) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 6, 5) on conflict do nothing;
insert into public.product_price_tiers (product_id, min_quantity, discount_percent) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 12, 10) on conflict do nothing;
insert into public.product_price_tiers (product_id, min_quantity, discount_percent) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 50, 15) on conflict do nothing;
insert into public.product_options (product_id, type, code, label_en, label_si, is_required, config, sort_order) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 'color'::public.option_type, 'inner_color', 'Inside colour', 'ඇතුළත වර්ණය', true, '{}'::jsonb, 10) on conflict (product_id, code) do nothing;
insert into public.product_option_values (option_id, label_en, label_si, value, modifier_type, price_modifier, width_in, height_in, swatch_hex, is_default, sort_order) values ((select id from public.product_options where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and code = 'inner_color'), 'White', 'සුදු', 'white', 'flat'::public.price_modifier_type, 0, null, null, '#FFFFFF', true, 10) on conflict (option_id, value) do nothing;
insert into public.product_option_values (option_id, label_en, label_si, value, modifier_type, price_modifier, width_in, height_in, swatch_hex, is_default, sort_order) values ((select id from public.product_options where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and code = 'inner_color'), 'Red', 'රතු', 'red', 'flat'::public.price_modifier_type, 150, null, null, '#C62828', false, 20) on conflict (option_id, value) do nothing;
insert into public.product_option_values (option_id, label_en, label_si, value, modifier_type, price_modifier, width_in, height_in, swatch_hex, is_default, sort_order) values ((select id from public.product_options where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and code = 'inner_color'), 'Black', 'කළු', 'black', 'flat'::public.price_modifier_type, 150, null, null, '#1F1F1F', false, 30) on conflict (option_id, value) do nothing;
insert into public.product_option_values (option_id, label_en, label_si, value, modifier_type, price_modifier, width_in, height_in, swatch_hex, is_default, sort_order) values ((select id from public.product_options where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and code = 'inner_color'), 'Blue', 'නිල්', 'blue', 'flat'::public.price_modifier_type, 150, null, null, '#1565C0', false, 40) on conflict (option_id, value) do nothing;
insert into public.product_options (product_id, type, code, label_en, label_si, is_required, config, sort_order) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 'text'::public.option_type, 'name_text', 'Name or message (optional)', 'නම හෝ පණිවිඩය (අත්‍යවශ්‍ය නැත)', false, '{"max_length":40}'::jsonb, 20) on conflict (product_id, code) do nothing;
insert into public.product_options (product_id, type, code, label_en, label_si, is_required, config, sort_order) values ((select id from public.products where slug = 'photo-mug-white-11oz'), 'photo_slots'::public.option_type, 'photos', 'Photos', 'ඡායාරූප', false, '{"count":3,"print_width_in":8,"print_height_in":3.5}'::jsonb, 30) on conflict (product_id, code) do nothing;
insert into public.product_templates (product_id, name_en, name_si, preview_key, config, sort_order) select (select id from public.products where slug = 'photo-mug-white-11oz'), 'Single photo', 'තනි ඡායාරූපය', '/templates/mug-single-photo.svg', '{"photo_slots":1,"text_fields":[]}'::jsonb, 10 where not exists (select 1 from public.product_templates where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and name_en = 'Single photo');
insert into public.product_templates (product_id, name_en, name_si, preview_key, config, sort_order) select (select id from public.products where slug = 'photo-mug-white-11oz'), 'Photo + name', 'ඡායාරූපය + නම', '/templates/mug-photo-name.svg', '{"photo_slots":1,"text_fields":["name"]}'::jsonb, 20 where not exists (select 1 from public.product_templates where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and name_en = 'Photo + name');
insert into public.product_templates (product_id, name_en, name_si, preview_key, config, sort_order) select (select id from public.products where slug = 'photo-mug-white-11oz'), '2-photo collage', 'ඡායාරූප 2ක කොලාජය', '/templates/mug-collage-2.svg', '{"photo_slots":2,"text_fields":[]}'::jsonb, 30 where not exists (select 1 from public.product_templates where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and name_en = '2-photo collage');
insert into public.product_templates (product_id, name_en, name_si, preview_key, config, sort_order) select (select id from public.products where slug = 'photo-mug-white-11oz'), 'Photo + message', 'ඡායාරූපය + පණිවිඩය', '/templates/mug-photo-message.svg', '{"photo_slots":1,"text_fields":["message","date"]}'::jsonb, 40 where not exists (select 1 from public.product_templates where product_id = (select id from public.products where slug = 'photo-mug-white-11oz') and name_en = 'Photo + message');
insert into public.products (category_id, slug, name_en, name_si, short_description_en, short_description_si, description_en, description_si, order_type, pricing_mode, base_price, price_per_sqft, min_sqft, production_days, express_days, express_surcharge_percent, design_fee, allow_customer_artwork, allow_design_service, requires_artwork, images, specs, is_featured, sort_order) select c.id, 'magic-colour-changing-mug', 'Magic Colour-Changing Mug', 'වර්ණය වෙනස් වන මැජික් මග්', 'Black when cold — your photo appears with hot tea.', 'සීතල විට කළු — උණු තේ දැමූ විට ඔබේ ඡායාරූපය පෙනේ.', 'A surprise gift: the mug looks plain black until a hot drink reveals your photo and message.', 'උණු පානයක් දැමූ විට ඔබේ ඡායාරූපය සහ පණිවිඩය මතු වන විශේෂ තෑග්ගක්.', 'fixed'::public.order_type, 'fixed'::public.pricing_mode, 1650, null, null, 2, 1, 50, 300, true, true, true, '[]'::jsonb, '[{"label_en":"Capacity","value_en":"11 oz / 330 ml"},{"label_en":"Care","value_en":"Hand wash only"}]'::jsonb, true, 20 from public.categories c where c.slug = 'mug-printing' on conflict (slug) do nothing;
insert into public.product_price_tiers (product_id, min_quantity, discount_percent) values ((select id from public.products where slug = 'magic-colour-changing-mug'), 6, 5) on conflict do nothing;
